const APP = {"id":"d40108eb-be56-48c3-b22a-7e2a86a09953","name":"Atelier · 이미지 디자인 스튜디오"};
const DEFAULTS = {"kind":"bag","name":"Everyday canvas tote","description":"내추럴 캔버스 소재의 데일리 토트백. 가로 36cm, 세로 32cm, 폭 12cm, 손잡이 길이 58cm. 안감을 넣고 차분한 샌드 컬러로 만들고 싶어요.","width":36,"height":32,"depth":12,"strapLength":58,"strapWidth":3,"sleeveLength":22,"sleeveWidth":20,"seam":1,"fabricWidth":150,"waste":15,"quantity":1,"fabricPrice":12000,"liningPrice":6000,"hardwarePrice":1800,"labor":18000,"development":50000,"lining":true,"currency":"KRW","color":"sand"};
const IMAGE_ASSETS=(globalThis.__LAUNCHPAD_DESIGN_ASSETS__||{bag:'',top:''});
function estimateFashion(input) {
  const number = (key, min, max) => { const value = Number(input[key]); if (!Number.isFinite(value) || input[key] === '' || input[key] == null || value < min || value > max) throw new Error(key + ' 값을 ' + min + ' ~ ' + max + ' 범위로 입력해 주세요.'); return value; };
  const kind = input.kind === 'top' ? 'top' : input.kind === 'bag' ? 'bag' : null;
  if (!kind) throw new Error('가방 또는 상의 종류를 선택해 주세요.');
  const width=number('width',5,180), height=number('height',5,180), seam=number('seam',0,5), fabricWidth=number('fabricWidth',30,300), waste=number('waste',0,80), quantity=number('quantity',1,200);
  if (!Number.isInteger(quantity)) throw new Error('제작 수량은 정수여야 합니다.');
  const money = key => number(key,0,10000000);
  const fabricPrice=money('fabricPrice'), liningPrice=money('liningPrice'), hardwarePrice=money('hardwarePrice'), labor=money('labor'), development=money('development');
  const add = (name,w,h,count,lining=false) => ({name,width:w+2*seam,height:h+2*seam,count,lining});
  let parts;
  if (kind === 'bag') {
    const depth=number('depth',2,80), strapLength=number('strapLength',5,200), strapWidth=number('strapWidth',1,12);
    parts=[add('앞·뒤판',width,height,2,true),add('옆판',depth,height,2,true),add('바닥판',width,depth,1,true),add('손잡이',strapWidth,strapLength,2)];
  } else {
    const sleeveLength=number('sleeveLength',5,80), sleeveWidth=number('sleeveWidth',5,60);
    parts=[add('몸판 바운딩 박스',width,height,2),add('소매 바운딩 박스',sleeveLength,sleeveWidth,2)];
  }
  const pack = (pieces) => {
    const expanded=[];
    for (const part of pieces) for (let count=0;count<part.count*quantity;count++) expanded.push({name:part.name,width:part.width,height:part.height});
    // Keep grain direction fixed; rotation is deliberately disallowed.
    expanded.sort((a,b)=>b.height-a.height||b.width-a.width);
    const rows=[];
    for (const piece of expanded) {
      if (piece.width > fabricWidth) throw new Error(piece.name + ' 재단 폭 ' + piece.width + 'cm가 원단 폭 ' + fabricWidth + 'cm보다 큽니다. 원단 폭을 늘려 주세요.');
      let row=rows.find(candidate=>candidate.usedWidth+piece.width<=fabricWidth+1e-9);
      if (!row) { row={height:piece.height,usedWidth:0,pieces:[]}; rows.push(row); }
      row.pieces.push({...piece,x:row.usedWidth}); row.usedWidth+=piece.width;
    }
    let cursor=0;
    for (const row of rows) { row.y=cursor; cursor+=row.height; }
    const area=expanded.reduce((sum,piece)=>sum+piece.width*piece.height,0)/10000;
    const layoutMeters=cursor/100, allowanceMeters=layoutMeters*(1+waste/100);
    const purchaseMeters=Math.max(0,Math.ceil((allowanceMeters-1e-9)*10)/10);
    return {rows,area,layoutMeters,allowanceMeters,purchaseMeters,utilization:cursor ? area/(fabricWidth*cursor/10000)*100 : 0,pieceCount:expanded.length};
  };
  const fabric=pack(parts), lining=pack(kind==='bag' && input.lining ? parts.filter(part=>part.lining) : []);
  const costs={fabric:fabric.purchaseMeters*fabricPrice,lining:lining.purchaseMeters*liningPrice,hardware:quantity*hardwarePrice,labor:quantity*labor,development};
  const total=Object.values(costs).reduce((sum,value)=>sum+value,0);
  return {kind,parts,fabric,lining,costs,total,perUnit:total/quantity,quantity,fabricWidth,waste,seam};
}
function parseFashionBrief(text, current) {
  const next={...current}, matched=[];
  if (/티셔츠|상의|셔츠|t-shirt|shirt/i.test(text)) { if (next.kind !== 'top') Object.assign(next,{kind:'top',width:54,height:62}); matched.push('상의'); }
  else if (/가방|토트|에코백|bag|tote/i.test(text)) { if (next.kind !== 'bag') Object.assign(next,{kind:'bag',width:36,height:32}); matched.push('가방'); }
  const specs=[['width',/(?:가로|단면(?:\s*폭)?|몸판\s*폭)\s*(\d+(?:\.\d+)?)\s*(?:cm|센티|센치)/i,'가로'],['height',/(?:세로|총장|몸판\s*길이)\s*(\d+(?:\.\d+)?)\s*(?:cm|센티|센치)/i,'세로'],['depth',/(?:깊이|(?<!단면\s)(?<!몸판\s)폭)\s*(\d+(?:\.\d+)?)\s*(?:cm|센티|센치)/i,'깊이'],['strapLength',/손잡이\s*(?:길이)?\s*(\d+(?:\.\d+)?)\s*(?:cm|센티|센치)/i,'손잡이'],['sleeveLength',/소매\s*(?:길이)?\s*(\d+(?:\.\d+)?)\s*(?:cm|센티|센치)/i,'소매']];
  for (const [key,expression,label] of specs) { const found=text.match(expression); if (found) { next[key]=Number(found[1]); matched.push(label+' '+found[1]+'cm'); } }
  const colors=[['sand',/샌드|내추럴|베이지|sand|beige/i],['ink',/네이비|검정|블랙|navy|black/i],['sage',/그린|초록|세이지|sage|green/i],['sky',/하늘|파랑|블루|blue/i]];
  for (const [color,expression] of colors) if(expression.test(text)){next.color=color; matched.push('컬러');break;}
  next.description=text;
  return {value:next,matched};
}

const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const key='atelier-projects-'+APP.id;
let current={...DEFAULTS}, saved=[], activeId=null, result=null, view='image';
try { const data=JSON.parse(localStorage.getItem(key)||'[]'); if(Array.isArray(data)) saved=data.filter(item=>item&&typeof item.id==='string'&&item.data&&typeof item.data==='object').slice(0,30); } catch {}
const colors={sand:{label:'샌드',fill:'#c8b396',shade:'#b39a79',light:'#e1d4bf'},ink:{label:'잉크',fill:'#405058',shade:'#2b3c43',light:'#6a7880'},sage:{label:'세이지',fill:'#a5b7a3',shade:'#809a82',light:'#c4d3bf'},sky:{label:'스카이',fill:'#a2becd',shade:'#7b9eaf',light:'#c1d4df'}};
const icons={spark:'<path d="m12 2 2.8 7.2L22 12l-7.2 2.8L12 22l-2.8-7.2L2 12l7.2-2.8L12 2z"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',folder:'<path d="M3 7V5a1 1 0 0 1 1-1h6l2 3h8a1 1 0 0 1 1 1v11a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V7z"/>',down:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',check:'<path d="m5 12 4 4L19 6"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 4H4v16h16v-6"/>',grid:'<path d="M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z"/>',ruler:'<path d="m4 17 13-13 4 4L8 21zM14 7l3 3M10 11l3 3M6 15l3 3"/>'};
function icon(name){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(icons[name]||icons.spark)+'</svg>';}
function format(value){return new Intl.NumberFormat('ko-KR',{style:'currency',currency:current.currency,maximumFractionDigits:current.currency==='KRW'?0:2}).format(value);}
const round=value=>Number(value.toFixed(2));
function notify(message,error=false){const el=$('#notice');el.textContent=message;el.className=error?'error':'';el.hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>{el.hidden=true;},6500);}
function input(label,name,unit,min,max,step=1){return '<label class="field">'+label+'<span class="input-wrap"><input name="'+name+'" aria-label="'+label+'" type="number" min="'+min+'" max="'+max+'" step="'+step+'" value="'+esc(current[name])+'" required><span>'+unit+'</span></span></label>';}
function render(){
$('#app').innerHTML='<header class="header"><a class="brand" href="#" aria-label="Atelier 홈"><span class="brandmark">a<span>↗</span></span><strong>atelier<span>DESIGN TO MAKE</span></strong></a><nav aria-label="주요 메뉴"><span class="nav-active">디자인 워크스페이스</span><button id="projects-nav">내 프로젝트 <span class="count">'+saved.length+'</span></button></nav><div class="header-end"><span class="local-pill"><i></i> 로컬 워크스페이스</span><span class="avatar">ME</span></div></header><main><section class="hero"><div><div class="eyebrow"><span></span> THE INDEPENDENT DESIGN STUDIO</div><h1>From an idea<br>to a <em>first sample.</em></h1><p>머릿속 디자인을 눈앞의 이미지로.<br>치수부터 재료, 예상 제작비까지 한 작업실에서.</p></div><div class="hero-note"><span class="editorial-flower" aria-hidden="true">✳</span><span class="hero-note-line"></span><p>A space for<br>things yet to be made.</p><span>DESIGN / MATERIAL / MAKE</span></div></section><section class="workspace-heading"><div><span class="project-dot"></span><input id="project-name" aria-label="프로젝트 이름" maxlength="80" value="'+esc(current.name)+'"><span class="draft-tag">'+(activeId?'저장한 디자인':'새 디자인')+'</span></div><div class="workspace-actions"><button class="quiet" id="new-project">'+icon('plus')+' 새 작업</button><button class="save-button" id="save-project">'+icon('folder')+' 저장하기</button></div></section><div class="workspace"><aside class="spec-panel"><div class="panel-heading"><span class="step">01</span><h2>디자인 브리프</h2><span class="mini-label">DEFINE</span></div><label class="description-label" for="description">어떤 디자인을 만들고 싶나요?</label><textarea id="description" maxlength="3000" rows="4">'+esc(current.description)+'</textarea><button class="parse-button" id="parse-brief">'+icon('spark')+' 설명에서 치수 불러오기 '+icon('arrow')+'</button><p class="helper">가로·세로·폭 + cm, 가방·상의, 지원 컬러를 읽어요.<br>명시하지 않은 값은 아래 기본값을 유지합니다.</p><div class="section-divider"></div><div class="field-title">제품 유형 <span>기본 형태</span></div><div class="segmented" role="group" aria-label="제품 유형"><button data-kind="bag" class="'+(current.kind==='bag'?'selected':'')+'">토트백</button><button data-kind="top" class="'+(current.kind==='top'?'selected':'')+'">베이식 상의</button></div><div class="field-title">치수 설정 <span>완성 치수 · cm</span></div><div class="field-grid">'+input(current.kind==='bag'?'가로':'몸판 단면','width','cm',5,180,.5)+input(current.kind==='bag'?'세로':'총장','height','cm',5,180,.5)+(current.kind==='bag'?input('깊이','depth','cm',2,80,.5)+input('손잡이 길이','strapLength','cm',5,200,.5)+input('손잡이 폭','strapWidth','cm',1,12,.5):input('소매 길이','sleeveLength','cm',5,80,.5)+input('소매 폭','sleeveWidth','cm',5,60,.5))+input('시접 가정','seam','cm',0,5,.5)+'</div><div class="field-title">컬러 무드 <span id="color-label">'+colors[current.color].label+'</span></div><div class="swatches">'+Object.entries(colors).map(([name,color])=>'<button data-color="'+name+'" class="swatch '+(name===current.color?'selected':'')+'" style="--swatch:'+color.fill+'" aria-label="'+color.label+' 컬러" aria-pressed="'+(name===current.color)+'">'+(name===current.color?icon('check'):'')+'</button>').join('')+'</div><div class="field-title">원단 & 수량 <span>산출 기준</span></div><div class="field-grid">'+input('원단 폭','fabricWidth','cm',30,300,1)+input('여유 손실률','waste','%',0,80,1)+input('제작 수량','quantity','개',1,200,1)+'</div>'+(current.kind==='bag'?'<label class="checkbox"><input id="lining" type="checkbox" '+(current.lining?'checked':'')+'><span>안감 포함</span><small>몸판 · 옆판 · 바닥판</small></label>':'<p class="helper top-note">상의는 몸판·소매의 사각형 외곽으로 계산합니다. 넥밴드·곡선·신축률·착용 여유는 별도 검토가 필요해요.</p>')+'</aside><section class="design-panel"><div class="panel-heading"><span class="step">02</span><h2>디자인 미리보기</h2><span class="live-badge">STUDIO VIEW</span></div><div class="canvas-toolbar"><div class="view-tabs"><button data-view="image" class="'+(view==='image'?'active':'')+'">'+icon('spark')+' 디자인 이미지</button><button data-view="diagram" class="'+(view==='diagram'?'active':'')+'">'+icon('ruler')+' 치수 개념도</button><button data-view="layout" class="'+(view==='layout'?'active':'')+'">'+icon('grid')+' 원단 배치</button></div><button class="icon-button" id="download-svg" aria-label="현재 도면 SVG 다운로드">'+icon('down')+'</button></div><div class="drawing-canvas" id="drawing-canvas"></div><div id="image-disclosure" class="image-disclosure"><span>AI 생성 이미지</span><p>치수 자동 반영 아님 · 샘플을 위해 생성한 컨셉 이미지예요. 입력한 치수와 컬러는 치수 개념도에서 확인하세요.</p></div><div class="canvas-caption"><span id="canvas-basis"><i></i> 입력 치수 기반 · 축척 없음</span><span id="canvas-meta"></span></div><div class="parts-section"><div class="subheading"><h3>작은 조각에서, 하나의 디자인으로</h3><span>시접 포함 / 1개 기준</span></div><div id="parts-list"></div></div><div class="assumption-note">'+icon('ruler')+'<p><strong>도면을 읽기 전에</strong><span>치수는 직접 입력한 값이며 자동 실측하지 않습니다. 개념도와 사각형 배치는 봉제용 실물 패턴이 아니에요. 첫 샘플 제작 전 패턴사와 치수·시접을 확인해 주세요.</span></p></div></section><aside class="estimate-panel"><div class="panel-heading"><span class="step">03</span><h2>예상 제작비</h2><span class="mini-label">ESTIMATE</span></div><div class="cost-card"><span class="cost-eyebrow">예상 제작비 · 전체 수량</span><strong id="total-cost"></strong><span class="cost-per-unit" id="unit-cost"></span><div class="cost-card-divider"></div><div><span>예상 겉감 필요량</span><b id="fabric-meters"></b></div><p>원단 배치 + 손실률 · 0.1m 단위 올림</p></div><div id="cost-breakdown" class="cost-breakdown"></div><button class="cost-edit-toggle" id="cost-edit-toggle" aria-expanded="false">단가와 공임 수정하기 <span>＋</span></button><div id="price-fields" class="price-fields" hidden><label class="field">계산 통화<select id="currency" aria-label="계산 통화">'+['KRW','USD','EUR'].map(currency=>'<option '+(current.currency===currency?'selected':'')+'>'+currency+'</option>').join('')+'</select></label><p class="helper">환율 변환 없이 입력한 단가를 선택 통화로 표시합니다.</p>'+input('겉감 단가','fabricPrice','/ m',0,10000000,1)+input('안감 단가','liningPrice','/ m',0,10000000,1)+input('부자재 묶음','hardwarePrice','/ 개',0,10000000,1)+input('봉제 공임','labor','/ 개',0,10000000,1)+input('패턴·개발비','development','1회',0,10000000,1)+'</div><p class="estimate-note">단가·공임은 샘플 가정값입니다.<br>세금·배송 제외 · 실제 업체 견적과 다를 수 있어요.</p><button class="primary" id="download-brief">제작 브리프 다운로드 '+icon('down')+'</button><div class="maker-card"><div class="maker-icon">↗</div><span class="eyebrow">MEET YOUR MAKER</span><h3>함께 만들 사람,<br>찾아볼까요?</h3><p>완성한 브리프로 조건을 비교하고<br>첫 샘플 견적을 문의해 보세요.</p><a id="maker-link" href="https://search.naver.com/search.naver?query='+encodeURIComponent(current.kind==='bag'?'가방 소량 샘플 제작 업체':'의류 상의 소량 샘플 제작 업체')+'" target="_blank" rel="noopener noreferrer">제작 업체 찾기 '+icon('external')+'</a><small>외부 검색 · 제휴·문의 전송 기능 없음</small></div></aside></div><footer><span>atelier © 2026</span><p>당신의 다음 아이디어가, 세상에 나오는 순간을 위해.</p><span>LOCAL FIRST. THOUGHTFULLY MADE.</span></footer></main><div id="notice" role="status" hidden></div><dialog id="projects-dialog"><div class="dialog-heading"><div><span class="eyebrow">YOUR DESIGN ARCHIVE</span><h2>내 프로젝트</h2></div><button id="close-dialog" class="icon-button" aria-label="닫기">×</button></div><p class="helper">이 브라우저에 저장됩니다. 기기 간 동기화되지 않아요.</p><div id="saved-list"></div></dialog>';
document.querySelectorAll('input[name]').forEach(el=>el.addEventListener('input',()=>{current[el.name]=el.value===''?'':Number(el.value);update();}));
$('#project-name').addEventListener('input',event=>{current.name=event.target.value;});$('#description').addEventListener('input',event=>{current.description=event.target.value;});
document.querySelectorAll('[data-kind]').forEach(button=>button.onclick=()=>{if(current.kind!==button.dataset.kind){current.kind=button.dataset.kind;Object.assign(current,current.kind==='bag'?{width:36,height:32}:{width:54,height:62});}render();});
document.querySelectorAll('[data-color]').forEach(button=>button.onclick=()=>{current.color=button.dataset.color;render();});
document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>{view=button.dataset.view;render();});
if($('#lining')) $('#lining').onchange=event=>{current.lining=event.target.checked;update();};
$('#parse-brief').onclick=()=>{const parsed=parseFashionBrief(current.description,current);try{estimateFashion(parsed.value);current=parsed.value;render();notify(parsed.matched.length?'반영: '+parsed.matched.join(' · ')+'. 나머지는 현재 입력값을 유지했어요.':'인식된 치수가 없어요. 가로 36cm, 세로 32cm처럼 적거나 아래 치수를 직접 수정해 주세요.');}catch(error){notify(error.message,true);}};
$('#currency').onchange=event=>{current.currency=event.target.value;update();};
$('#cost-edit-toggle').onclick=()=>{const open=$('#price-fields').hidden;$('#price-fields').hidden=!open;$('#cost-edit-toggle').setAttribute('aria-expanded',String(open));$('#cost-edit-toggle span').textContent=open?'−':'＋';};
$('#save-project').onclick=saveProject;$('#projects-nav').onclick=openArchive;$('#close-dialog').onclick=()=>$('#projects-dialog').close();
$('#new-project').onclick=()=>{current={...DEFAULTS};activeId=null;view='image';render();notify('새 디자인을 시작했어요. 저장한 작업은 내 프로젝트에서 열 수 있어요.');};
$('#download-svg').onclick=()=>{if(result){download((current.name||'atelier')+'-concept.svg',view==='layout'?layout():diagram(),'image/svg+xml');notify('치수 개념도를 SVG로 저장했어요. 제작용 패턴은 아닙니다.');}};
$('#download-brief').onclick=exportBrief;
update();
}
function update(){
