function layout(){const data=result.fabric,scale=Math.min(455/current.fabricWidth,355/Math.max(data.layoutMeters*100,1));const x=(600-current.fabricWidth*scale)/2,y=63;let svg=svgStart('원단 폭 '+current.fabricWidth+'cm, 고정 방향 원단 배치');svg+='<rect x="'+x+'" y="'+y+'" width="'+(current.fabricWidth*scale)+'" height="'+(data.layoutMeters*100*scale)+'" fill="#f0ebe0" stroke="#aab5a5" stroke-width="1"/>';let index=0;for(const row of data.rows)for(const piece of row.pieces){const px=x+piece.x*scale,py=y+row.y*scale,pw=piece.width*scale,ph=piece.height*scale;svg+='<rect x="'+px+'" y="'+py+'" width="'+pw+'" height="'+ph+'" fill="'+[colors[current.color].fill,colors[current.color].light,colors[current.color].shade][index++%3]+'" stroke="#fcfbf7" stroke-width="1"/>';if(pw>35&&ph>22)svg+='<text x="'+(px+pw/2)+'" y="'+(py+ph/2)+'" text-anchor="middle" font-size="'+Math.min(10,ph/4)+'">'+esc(piece.name)+'</text>';}
