function persist(){try{localStorage.setItem(key,JSON.stringify(saved));return true;}catch{notify('저장 공간이 부족하거나 이 브라우저에서 저장을 허용하지 않아요. 브리프를 다운로드해 보관해 주세요.',true);return false;}}
function saveProject(){if(!result){notify('치수 오류를 먼저 수정해 주세요.',true);return;}if(!current.name.trim()){notify('프로젝트 이름을 입력해 주세요.',true);$('#project-name').focus();return;}const id=activeId||globalThis.crypto?.randomUUID?.()||'p-'+Date.now();const old=saved;const entry={id,updatedAt:new Date().toISOString(),data:{...current}};saved=[entry,...saved.filter(item=>item.id!==id)].slice(0,30);if(persist()){activeId=id;render();notify('디자인을 이 브라우저에 저장했어요.');}else saved=old;}
