function renderArchive(){$('#saved-list').innerHTML=saved.length?saved.map(item=>'<article class="archive-item"><button data-load="'+esc(item.id)+'"><span>'+esc(item.data.kind==='top'?'BASIC TOP':'TOTE BAG')+'</span><h3>'+esc(item.data.name||'이름 없는 디자인')+'</h3><p>'+esc(item.data.width)+' × '+esc(item.data.height)+' cm · '+esc(new Date(item.updatedAt).toLocaleDateString('ko-KR'))+'</p></button><button class="delete-project" data-delete="'+esc(item.id)+'" aria-label="'+esc(item.data.name||'디자인')+' 삭제">삭제</button></article>').join(''):'<div class="archive-empty">아직 저장한 디자인이 없어요.<br>작업 화면에서 저장하기를 눌러 보관해 보세요.</div>';document.querySelectorAll('[data-load]').forEach(button=>button.onclick=()=>{const item=saved.find(item=>item.id===button.dataset.load);try{const data={...DEFAULTS,...item.data};estimateFashion(data);if(!colors[data.color]||!['KRW','USD','EUR'].includes(data.currency))throw new Error('저장된 설정을 읽을 수 없어요.');current=data;activeId=item.id;render();notify('저장한 디자인을 불러왔어요.');}catch(error){notify(error.message,true);}});document.querySelectorAll('[data-delete]').forEach(button=>button.onclick=()=>{const old=saved;saved=saved.filter(item=>item.id!==button.dataset.delete);if(persist()){if(activeId===button.dataset.delete)activeId=null;renderArchive();$('#projects-nav .count').textContent=saved.length;notify('저장한 프로젝트를 삭제했어요. 현재 작업 화면은 유지됩니다.');}else saved=old;});}
function download(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name.replace(/[\\/:*?"<>|]/g,'-');document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function exportBrief(){if(!result)return;const brief={format:'atelier-production-brief-v1',createdAt:new Date().toISOString(),design:{...current},estimate:result,limitations:['입력 치수 기반 개념도이며 사진 실측이나 봉제용 실물 패턴이 아닙니다.','사각형 부품을 원단 결 방향을 유지하며 행에 배치합니다. 회전·최적 배치는 적용하지 않습니다.','상의는 몸판·소매 바운딩 박스 추정입니다. 넥밴드·곡선·소맷단·신축률은 반영하지 않습니다.','손실률을 배치 길이에 추가하고 0.1m 단위로 올림합니다.','단가·공임·개발비는 사용자가 입력한 가정이며 세금·배송비·실제 업체 견적이 아닙니다.','통화 선택은 환율 변환을 수행하지 않습니다.','제작 가능 여부, 원단 수축률, 부자재 구성, 최소 수량을 업체와 확인해야 합니다.']};download((current.name||'atelier')+'-brief.json',JSON.stringify(brief,null,2),'application/json');notify('도면·재료·비용 계산 기준을 담은 제작 브리프를 저장했어요.');}
